Each name list is fitted by `fitNames` to the room a value has
(`shortcut.HeaderValueWidth`), so the `+N` is never lost: all the names, else
the first k names then `+N`, else `+N` alone. `Skipped` carries the hint
` (type N+ characters)`, which is the first thing dropped when the header is
narrow. The summary has a budget of `shortcut.HeaderRows` (7) lines, `Images`
included; classes after the sixth are left out. Before the first
`WindowSizeMsg` nothing is abbreviated. At level 2 (tags) the header is the
usual tag count.

Limit, accepted (R2): below about 50 columns `HeaderValueWidth` is 0 or 1,
nothing fits, `fitNames` returns `+N` anyway and the router clips it.

Logging, by verdict, through `logSearchOutcome` (the alias falls back to the
entry key):
- `failed`: `ERROR [oci_resources] image search on <alias>: <cause>`;
- `refused`: `INFO [oci_resources] image search on <alias>: unsupported or
  refused: <cause>` (a refusal is expected for dhi.io and for a registry whose catalog
  is disabled, forbidden or not under the entry's prefix, so it does not fill
  the error log);
- `ok` and `no result`: nothing.

The cause is `searchErrorCause(err)`: a `*url.Error` keeps only its Op and Err
(the URL carries the typed text and can carry credentials), then
`jobs.SafeCause`. Nothing else reaches the log. Nothing reaches the screen
is what a registry is reached by, and both directions derive from it — the browse
asks `<url>/v2/<prefix>/<repo>/tags/list` (through `oci.ListRegistryTags`, the one tag lister, which follows `Link` pagination), the pull reference is
`<url>/<prefix>/<repo>:<tag>` — so they cannot mean two different repositories.
That disagreement is exactly what D39 was: `NexusDetector` synthesised a member
as `host/repository/<name>`, which browses (200) and cannot pull (404), because
the Docker client puts `/v2/` first and the whole path after it.

Like `provider`, it is **declared, never sniffed**. Whether a repository answers
on a path prefix, a connector port or a subdomain is a setting on that repository
(`docker.httpPort`, `docker.httpsPort`, `docker.subdomain`), and the one endpoint
carrying it answers 403 to an ordinary pull account — the same endpoint that
would say what a group's members are. An instance that refuses one refuses both,
so guessing is not a fallback, it is the defect.
func UsesCredentials(mode string) bool {
	return mode != AuthAnonymous && mode != AuthInherit
}

// IsNexusGroup reports whether item is a group served by Nexus, the one kind of
// group whose content can only be listed from the discovered-members cache.
func IsNexusGroup(item RegistryItem) bool {
	return item.Kind == KindGroup && item.Provider == ProviderNexus
}

// Providers returns the declared providers in the order a form cycles them,
// generic first because it is the default for a group that says nothing.
func Providers() []string {
	return []string{ProviderGeneric, ProviderNexus, ProviderHarbor, ProviderArtifactory, ProviderGitLab}
}

// Kinds returns the two kinds in the order a form cycles them.
// answered with no result: with a cache-only list, it means nothing is cached.
const cachedNoResultMark = " (no result)"

// summarizeSearch sorts the lot's keys into classes. Pure; names are label(key),
// in the order of keys. cachedOnly says which keys list cached content only; a
// concerned key that answered ok or with no result goes to CachedOnly (the
// no-result one marked, and not in NoResult), a partial one also to Partial.
func summarizeSearch(keys []string, outcomes map[string]imagesearch.Outcome, live bool,
	label func(key string) string, cachedOnly func(key string) bool) searchSummary {
	var s searchSummary
	for _, k := range keys {
		oc, ok := outcomes[k]
		if !ok {
			if live {
				s.Pending++
			} else {
				s.Interrupted = append(s.Interrupted, label(k))
			}
			continue
		}
		switch oc.Verdict {
		case imagesearch.VerdictFailed:
			s.Failed = append(s.Failed, label(k))
		case imagesearch.VerdictRefused:
			s.Refused = append(s.Refused, label(k))
		case imagesearch.VerdictNoResult:
			if oc.Skipped {
				s.Skipped = append(s.Skipped, label(k))
				continue
			}
			if oc.Partial {
				s.Partial = append(s.Partial, label(k))
			}
			if cachedOnly(k) {
				s.CachedOnly = append(s.CachedOnly, label(k)+cachedNoResultMark)
				continue
			}
			s.NoResult = append(s.NoResult, label(k))
		case imagesearch.VerdictOK:
			if oc.Partial {
				s.Partial = append(s.Partial, label(k))
			}
			if cachedOnly(k) {
				s.CachedOnly = append(s.CachedOnly, label(k))
			}
		}
	}
	return s
}

	e := b.entryFor(key)
	if e == nil {
		return key
	}
	if a := entryAlias(*e); a != "" {
		return a
	}
	if e.URL != "" {
		return e.URL
	}
	return key
}

// searchHeaderInfo is the level 1 header: the image count, then one line per class
// that has something to say (nothing when every registry answered: only the count).
// Order: Pending or Interrupted, Failed (red), Refused, Partial (orange), Cached only (orange), No result,
// Skipped (grey). Each name list is abbreviated by fitNames to the room the header
// gives a value, so a +N is never lost; Skipped drops its hint first. termWidth 0
// or less means the width is not known yet. At most shortcut.HeaderRows lines.
func searchHeaderInfo(images int, s searchSummary, termWidth int) []shortcut.HeaderInfo {
	type line struct {
		key    string
		names  []string
		count  string // a ready value, instead of names
		suffix string
		style  lipgloss.Style
	}
	warn := theme.HeaderWarnValueStyle()
	var lines []line
	if s.Pending > 0 {
		lines = append(lines, line{key: "Pending", count: fmt.Sprintf("%d", s.Pending), style: theme.HeaderValueStyle})
	}
	lines = append(lines,
		line{key: "Interrupted", names: s.Interrupted, style: warn},
		line{key: "Failed", names: s.Failed, style: theme.SeverityTextStyle("CRITICAL")},
		line{key: "Refused", names: s.Refused, style: warn},
		line{key: "Partial", names: s.Partial, style: warn},
		line{key: "Cached only", names: s.CachedOnly, style: warn},
		line{key: "No result", names: s.NoResult, style: theme.DimStyle},
		line{key: "Skipped", names: s.Skipped, suffix: skippedHint, style: theme.DimStyle},
	)
	var kept []line
	keys := []string{"Images"}
	for _, l := range lines {
		if l.count == "" && len(l.names) == 0 {
			continue
		}
		// The budget is HeaderRows lines: Images plus six classes. Pending and
		// Interrupted exclude each other, which leaves seven classes; Skipped
		// (last) is the one cut when all the others are present at once, which a
		// short query (every catalog walk skipped) makes practically unreachable.
		// A new line (IS-14) must revisit this bound rather than be cut silently.
		if len(kept)+1 >= shortcut.HeaderRows {
			break
		}
		kept = append(kept, l)
		keys = append(keys, l.key)
	}
	room := noWidthLimit
	if termWidth > 0 {
		room = shortcut.HeaderValueWidth(termWidth, keys)
		alias := browserAlias(reg)
		// Members share their group's host and therefore its single credential
		// entry, so they share the decision the group made about using it.
		mode := config.ResolveAuthMode(reg, nil)

		members := groups[reg.Slug].Members
		if reg.Kind != config.KindGroup || len(members) == 0 {
			// A group nobody has discovered yet is offered as itself: it is a
			// pullable registry too, and hiding it would be worse than listing
			// it without the members it may have.
			b.rows = append(b.rows, pickerRow{label: alias, entry: len(b.entries)})
			b.entries = append(b.entries, browserRegistryEntry{
				URL: reg.URL, Alias: alias, Slug: reg.Slug, authMode: mode,
				repoPrefix: reg.RepoPrefix,
				key:        reg.Slug,
				cachedOnly: listsCacheOnly(reg, bySlug),
			})
			continue
		}

		b.rows = append(b.rows, pickerRow{groupSlug: reg.Slug, label: alias, entry: -1})
		for _, m := range members {
			b.rows = append(b.rows, pickerRow{label: "  " + m.Alias, entry: len(b.entries)})
			b.entries = append(b.entries, browserRegistryEntry{
				URL:         m.URL,
				Alias:       m.Alias,
				repoPrefix:  m.RepoPrefix,
				Slug:        reg.Slug,
				ParentAlias: alias,
				ParentSlug:  reg.Slug,
				parentURL:   reg.URL,
				authMode:    mode,
				cachedOnly:  config.IsNexusGroup(reg),
				key:         memberKey(reg.Slug, m.URL, m.RepoPrefix),
			})
		}
	}

	b.selectedRegs = make(map[string]bool, len(b.entries))
	for _, e := range b.entries {
		b.selectedRegs[e.key] = !deselected[e.key]
	}
}

// listsCacheOnly reports whether reg can only be listed from the cache: it is a
// Nexus group, or it declares a Nexus group as its parent (Q-B ii).
func listsCacheOnly(reg config.RegistryItem, bySlug map[string]config.RegistryItem) bool {
	if config.IsNexusGroup(reg) {
		return true
	}
	return reg.Parent != "" && config.IsNexusGroup(bySlug[reg.Parent])
}

